CREATE TABLE IF NOT EXISTS `MatchPreviewInfo` (`id` TEXT NOT NULL, `event` TEXT NOT NULL, `series` TEXT NOT NULL, `status` TEXT NOT NULL, `team1` TEXT NOT NULL, `team2` TEXT NOT NULL, `time` TEXT, `eventId` TEXT NOT NULL DEFAULT '', `markedFav` INTEGER NOT NULL DEFAULT 0, `fromTeamsFav` INTEGER NOT NULL DEFAULT 0, `fromEventsFav` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `MatchInfo` (`id` TEXT NOT NULL, `event` TEXT NOT NULL, `head2head` TEXT NOT NULL, `note` TEXT NOT NULL, `score` TEXT NOT NULL, `teams` TEXT NOT NULL, `bans` TEXT NOT NULL, `videos` TEXT NOT NULL, `matchData` TEXT NOT NULL, `mapCount` INTEGER NOT NULL, `markedFav` INTEGER NOT NULL DEFAULT 0, `fromTeamsFav` INTEGER NOT NULL DEFAULT 0, `fromEventsFav` INTEGER NOT NULL DEFAULT 0, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `TournamentPreview` (`dates` TEXT NOT NULL, `id` TEXT NOT NULL, `img` TEXT NOT NULL, `location` TEXT NOT NULL, `prize` TEXT NOT NULL, `status` TEXT NOT NULL, `title` TEXT NOT NULL, `markedFav` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
