CREATE TABLE IF NOT EXISTS `TeamDetails` (`id` TEXT NOT NULL, `country` TEXT NOT NULL, `img` TEXT NOT NULL, `name` TEXT NOT NULL, `rank` INTEGER NOT NULL, `region` TEXT NOT NULL, `roster` TEXT NOT NULL, `tag` TEXT, `twitter` TEXT, `upcoming` TEXT NOT NULL, `completed` TEXT NOT NULL, `website` TEXT, `points` INTEGER, `createdAt` INTEGER NOT NULL, `markedFav` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
